import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';
import '../../core/theme/app_theme.dart';
import '../../services/api_service.dart';

class StudentsScreen extends StatefulWidget{const StudentsScreen({super.key});@override State<StudentsScreen> createState()=>_StudentsScreenState();}
class _StudentsScreenState extends State<StudentsScreen>{
 List students=[];List<String> subjects=[];bool loading=true;
 static const fallback=['العربية','اللغة الإنجليزية','الرياضيات','العلوم','الدراسات الاجتماعية','Math','Science','English','Arabic','German','French','Spanish','Quran','Chemistry','Physics','Biology','History','Geography','Philosophy'];
 List<dynamic> list(dynamic v){if(v is List)return List<dynamic>.from(v);if(v is Map&&v['data'] is List)return List<dynamic>.from(v['data']);if(v is Map&&v['data'] is Map&&v['data']['data'] is List)return List<dynamic>.from(v['data']['data']);return[];}
 int id(dynamic v)=>int.tryParse('${v['id']}')??0;String subjectName(dynamic v)=>v is Map?'${v['subject']??v['name']??''}':'$v';
 void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e'.replaceFirst('Exception: ',''))));
 @override void initState(){super.initState();load();}
 Future<void> load()async{if(mounted)setState(()=>loading=true);try{students=list(await ApiService.get('students'));}catch(e){msg(e);}try{final s=list(await ApiService.get('subjects')).map(subjectName).where((x)=>x.trim().isNotEmpty).toSet().toList();subjects=s.isEmpty?fallback:s;}catch(_){subjects=fallback;}if(mounted)setState(()=>loading=false);}
 Future<void> editForm({Map<String,dynamic>? existing})async{final name=TextEditingController(text:'${existing?['name']??''}'),phone=TextEditingController(text:'${existing?['phone']??''}'),parent=TextEditingController(text:'${existing?['parent_name']??''}'),grade=TextEditingController(text:'${existing?['grade']??''}');final selected=<String>{...list(existing?['subjects']).map(subjectName)};final form=GlobalKey<FormState>();final saved=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(c,setState){return AlertDialog(title:Text(existing==null?'إضافة طالب':'تعديل بيانات الطالب'),content:SizedBox(width:520,child:SingleChildScrollView(child:Form(key:form,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'اسم الطالب *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:phone,decoration:const InputDecoration(labelText:'هاتف الطالب')),TextFormField(controller:parent,decoration:const InputDecoration(labelText:'اسم ولي الأمر')),TextFormField(controller:grade,decoration:const InputDecoration(labelText:'الصف')),const SizedBox(height:8),const Text('المواد المشترك بها',style:TextStyle(fontWeight:FontWeight.bold)),...subjects.map((s)=>CheckboxListTile(dense:true,value:selected.contains(s),title:Text(s),onChanged:(v){setState((){if(v==true){selected.add(s);}else{selected.remove(s);}});})),])))),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(form.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))]);}));if(saved==true){try{final body={'name':name.text.trim(),'phone':phone.text.trim(),'parent_name':parent.text.trim(),'grade':grade.text.trim(),'status':'active','subjects':selected.toList()};if(existing==null){await ApiService.post('students',body);}else{await ApiService.put('students/${id(existing)}',body);}await load();}catch(e){msg(e);}}for(final c in[name,phone,parent,grade])c.dispose();}
 Future<void> openUrl(String raw)async{final u=Uri.tryParse(raw);if(u!=null&&await canLaunchUrl(u)){await launchUrl(u,mode:LaunchMode.externalApplication);}else{msg('الرابط غير صالح');}}
 Future<void> details(int studentId)async{try{final r=await ApiService.get('academic/students/$studentId');final d=r is Map&&r['data'] is Map?r['data']:r;final st=d['student'] is Map?d['student']:<String,dynamic>{};final resources=list(d['resources']),evaluations=list(d['evaluations']),plans=list(d['plans']);if(!mounted)return;await showDialog(context:context,builder:(dialog)=>AlertDialog(title:Text('${st['name']??'الطالب'}'),content:SizedBox(width:620,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('المواد: ${list(st['subjects']).map(subjectName).join('، ')}'),Text('المدرسون: ${list(st['teachers']).map((x)=>x is Map?'${x['name']??''}':'').join('، ')}'),Text('المجموعات: ${list(st['groups']).map((x)=>x is Map?'${x['name']??''}':'').join('، ')}'),Text('الحصص: ${list(st['lessons']).length} • الاشتراكات: ${list(st['subscriptions']).length} • المدفوعات: ${list(st['payments']).length}'),const Divider(),const Text('خطة الحصص الشهرية',style:TextStyle(fontWeight:FontWeight.bold)),...plans.map((p)=>Text('• ${p['subject']}: ${p['completed_lessons']??0}/${p['monthly_lessons']??0}')),const Divider(),const Text('التقييمات',style:TextStyle(fontWeight:FontWeight.bold)),...evaluations.map((e)=>Text('• ${e['title']??'تقييم'} — ${e['score']??'-'}%')),const Divider(),const Text('الواجبات والامتحانات والروابط والمرفقات',style:TextStyle(fontWeight:FontWeight.bold)),...resources.map((x)=>ListTile(dense:true,title:Text('${x['title']??''}'),subtitle:Text('${x['type']??''} • ${x['description']??''}'),trailing:x['url']==null?null:IconButton(onPressed:()=>openUrl('${x['url']}'),icon:const Icon(Icons.open_in_new))))]))),actions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
 Future<void> remove(Map<String,dynamic> s)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف الطالب'),content:Text('حذف ${s['name']??''}؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('students/${id(s)}');await load();}catch(e){msg(e);}}}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('الطلاب'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>editForm(),backgroundColor:AppColors.red,icon:const Icon(Icons.person_add),label:const Text('إضافة طالب')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:students.isEmpty?ListView(children:const[SizedBox(height:180),Center(child:Text('لا يوجد طلاب بعد.'))]):ListView.builder(padding:const EdgeInsets.fromLTRB(16,12,16,90),itemCount:students.length,itemBuilder:(context,index){final s=Map<String,dynamic>.from(students[index]);return Card(child:ListTile(onTap:()=>details(id(s)),leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${s['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${s['phone']??''}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='details')details(id(s));if(v=='edit')editForm(existing:s);if(v=='delete')remove(s);},itemBuilder:(context)=>const[PopupMenuItem(value:'details',child:Text('التفاصيل')),PopupMenuItem(value:'edit',child:Text('تعديل')),PopupMenuItem(value:'delete',child:Text('حذف'))])));}))));}
}
